package run.ikaros.reading; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException;
@Service public class PersistentReadingPreferenceService implements ReadingPreferenceService{private final ReadingPreferenceRepository repository;private final ReadingWorkRepository works;public PersistentReadingPreferenceService(ReadingPreferenceRepository r,ReadingWorkRepository w){repository=r;works=w;}
 @Override public Mono<ReadingPreferenceView> update(UUID o,ReadingPreferenceScope scope,String kind,UUID workId,UpdateReadingPreferenceRequest r){if(scope==null)return Mono.error(new IllegalArgumentException("偏好作用域不能为空"));if(scope==ReadingPreferenceScope.WORK&&workId==null)return Mono.error(new IllegalArgumentException("WORK 作用域需要 workId"));Mono<Void> owned=scope==ReadingPreferenceScope.WORK?works.findById(workId).filter(w->w.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Work 不存在或无权访问"))).then():Mono.empty();return owned.then(repository.findByOwnerIdAndScopeAndReadingKindAndWorkId(o,scope,kind,workId).flatMap(old->repository.save(new ReadingPreferenceEntity(old.id(),o,scope,kind,workId,r.settings(),Instant.now(),old.version()))).switchIfEmpty(repository.save(new ReadingPreferenceEntity(null,o,scope,kind,workId,r.settings(),Instant.now(),null)))).map(this::view);}
 @Override public Mono<ReadingPreferenceView> get(UUID o,ReadingPreferenceScope scope,String kind,UUID workId){return repository.findByOwnerIdAndScopeAndReadingKindAndWorkId(o,scope,kind,workId).switchIfEmpty(Mono.error(new NotFoundException("Reading Preference 不存在"))).map(this::view);}private ReadingPreferenceView view(ReadingPreferenceEntity e){return new ReadingPreferenceView(e.id(),e.scope(),e.readingKind(),e.workId(),e.settings(),e.updatedAt());}}
